    """Skip event sets referencing nodes/links the topology lacks."""
    names = set(TOPOS[topo_name]["nodes"])
    links = {frozenset((l["from"], l["to"])) for l in TOPOS[topo_name]["links"]}
    for e in events:
        if "node" in e and e["node"] not in names:
            return False
        if "from" in e and frozenset((e["from"], e["to"])) not in links:
            return False
    return True


